import { readFileSync } from 'fs';
import pg from './node_modules/pg/lib/index.js';
const { Pool } = pg;
const rawUrl = String(process.env.DATABASE_URL||'');
const url = (() => { try { const u = new URL(rawUrl); ['sslmode','sslcert','sslkey','sslrootcert','sslpassword'].forEach(p=>u.searchParams.delete(p)); return u.toString(); } catch { return rawUrl; } })();
let ssl; try { ssl = { rejectUnauthorized: true, ca: readFileSync('./certs/rds-ca-bundle.pem') }; } catch { ssl = { rejectUnauthorized: false }; }
const pool = new Pool({ connectionString: url, ssl, max: 1 });
const c = await pool.connect();
const { rows: dist } = await c.query('SELECT municipality_id, COUNT(*)::int AS cnt FROM app_units GROUP BY municipality_id ORDER BY cnt DESC');
console.log('app_units municipality_id distribution:');
dist.forEach(r => console.log('  [' + r.municipality_id + '] count=' + r.cnt));
const { rows: notInMun } = await c.query('SELECT municipality_id, COUNT(*)::int AS cnt FROM app_units WHERE municipality_id NOT IN (SELECT ibge_code FROM municipalities) GROUP BY municipality_id');
console.log('NOT IN municipalities: ' + JSON.stringify(notInMun));
const { rows: munSample } = await c.query("SELECT ibge_code, name FROM municipalities WHERE ibge_code = '3534401' OR ibge_code = '' LIMIT 5");
console.log('municipalities check: ' + JSON.stringify(munSample));
c.release(); await pool.end();
